From 3b9b57af977a9b4f84ef23a1dee6a002c0bc6e0a Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 17:20:54 +0100
Subject: [PATCH] kded: Keep global mute when a newly added device restores its
 volume

With global mute on, any volume change broke it, including the one the
sound server makes right after a device appears to restore its saved
volume. Changes to a device in its first seconds now keep it muted.

BUG: 511576
---
 src/kded/audioshortcutsservice.cpp | 15 ++++++++++++---
 src/kded/audioshortcutsservice.h   |  4 ++++
 2 files changed, 16 insertions(+), 3 deletions(-)

diff --git a/src/kded/audioshortcutsservice.cpp b/src/kded/audioshortcutsservice.cpp
index b7e42fa2..4ae078d0 100644
--- a/src/kded/audioshortcutsservice.cpp
+++ b/src/kded/audioshortcutsservice.cpp
@@ -12,6 +12,7 @@
 #include <QDBusMessage>
 #include <QGuiApplication>
 #include <QStringBuilder>
+#include <QTimer>

 #include <KGlobalAccel>
 #include <KLocalizedString>
@@ -451,7 +452,14 @@ void AudioShortcutsService::handleNewSink(const QModelIndex &parent, int first,
     const bool globalMute = m_globalConfig->globalMuteSinks();

     for (int i = first; i <= last; ++i) {
-        applyGlobalSinkMute(m_sinkModel->index(i, 0), globalMute, globalMuteMutedDevices);
+        const auto index = m_sinkModel->index(i, 0);
+        applyGlobalSinkMute(index, globalMute, globalMuteMutedDevices);
+
+        const QString name = m_sinkModel->data(index, m_sinkModel->role("Name"_ba)).toString();
+        m_newSinks.insert(name);
+        QTimer::singleShot(std::chrono::seconds(3), this, [this, name]() {
+            m_newSinks.remove(name);
+        });
     }

     m_globalConfig->setGlobalMuteSinksMutedDevices(globalMuteMutedDevices);
@@ -485,14 +493,15 @@ void AudioShortcutsService::handleSinkDataChanged(const QModelIndex &topLeft, co
         const bool volumeChanged = roles.contains(m_sinkModel->role("Volume"_ba));
         const bool mutedChanged = roles.contains(m_sinkModel->role("Muted"_ba));
         const bool isUnmuted = !m_sinkModel->data(index, m_sinkModel->role("Muted"_ba)).toBool();
+        const bool isNewSink = m_newSinks.contains(m_sinkModel->data(index, m_sinkModel->role("Name"_ba)).toString());

-        if (activePortIndexChanged) {
+        if (activePortIndexChanged || (globalMute && isNewSink && mutedChanged && isUnmuted)) {
             // Apply global mute to new device
             applyGlobalSinkMute(index, globalMute, globalMuteMutedDevices);

             m_globalConfig->setGlobalMuteSinksMutedDevices(globalMuteMutedDevices);
             m_globalConfig->save();
-        } else if (globalMute && (volumeChanged || (mutedChanged && isUnmuted))) {
+        } else if (globalMute && !isNewSink && (volumeChanged || (mutedChanged && isUnmuted))) {
             // Changes to volume or unmuting break global mute
             disableGlobalSinkMute();
         }
diff --git a/src/kded/audioshortcutsservice.h b/src/kded/audioshortcutsservice.h
index 26cf38d8..66a60a96 100644
--- a/src/kded/audioshortcutsservice.h
+++ b/src/kded/audioshortcutsservice.h
@@ -7,6 +7,8 @@

 #include <memory>

+#include <QSet>
+
 #include <KConfigWatcher>
 #include <kdedmodule.h>

@@ -86,5 +88,7 @@ private:
     PreferredDevice m_preferredDevice;
     QMetaObject::Connection m_preferredSinkVolumeConnection;
     std::unique_ptr<MutedMicrophoneReminder> m_mutedMicrophoneReminder;
+    // Sinks just added, whose volume the sound server may still be restoring
+    QSet<QString> m_newSinks;
     KDBusPropertiesChangedAdaptor m_adaptor = {QStringLiteral("/modules/audioshortcutsservice"), this};
 };
